import { WatchlistStore } from '../app/watchlist-store';
import { WatchItem } from '../app/movie';

describe('WatchlistStore ordering', () => {
  it('exposes sortedItems with unwatched movies before watched ones', () => {
    const store = new WatchlistStore();
    const watched: WatchItem = { id: 1, title: 'Watched One', watched: true };
    const unwatched: WatchItem = { id: 2, title: 'Unwatched One', watched: false };
    const watched2: WatchItem = { id: 3, title: 'Watched Two', watched: true };
    const unwatched2: WatchItem = { id: 4, title: 'Unwatched Two', watched: false };
    [watched, unwatched, watched2, unwatched2].forEach((m) => store.add({
      id: m.id, title: m.title, release_date: '', poster_path: null, overview: '',
    } as any));
    store['toggleWatched'](1);
    store['toggleWatched'](3);
    expect(store.sortedItems().map((m) => m.watched)).toEqual([false, false, true, true]);
    expect(store.sortedItems().map((m) => m.id)).toEqual([2, 4, 1, 3]);
  });
});

